/* Meshes built with the tools of diskpp: hexagonal meshes of the FVCA5
 * benchmark, unstructured simplicial meshes generated by gmsh. These headers
 * define non-inline functions: they are included in this translation unit
 * only. */
#include <cstdio>
#include <fstream>
#include <stdexcept>
#include <string>

#include "diskpp/mesh/meshgen.hpp"
#include "diskpp/loaders/loader.hpp"
#include "meshes.hpp"

namespace unfitted_meshes {

void make_hexagon_mesh(disk::generic_mesh<double,2>& msh, size_t level)
{
    auto mesher = disk::make_fvca5_hex_mesher(msh);
    mesher.make_level(level);
}

namespace {

/* Mesh the geometry of a temporary .geo file with gmsh */
template<typename Mesh>
void
gmsh_mesh(Mesh& msh, const std::string& geo)
{
#ifdef HAVE_GMSH
    const std::string filename = "unfitted_HHO_gmsh.geo";
    {
        std::ofstream ofs(filename);
        ofs << geo;
    }
    disk::gmsh_geometry_loader<Mesh> loader;
    bool ok = loader.read_mesh(filename);
    std::remove(filename.c_str());
    if (!ok)
        throw std::runtime_error("gmsh could not mesh the domain");
    loader.populate_mesh(msh);
#else
    throw std::runtime_error("The unstructured meshes need gmsh (diskpp built without HAVE_GMSH)");
#endif
}

} // namespace

void make_gmsh_mesh(disk::simplicial_mesh<double,2>& msh, double lc)
{
    std::string geo =
        "lc = " + std::to_string(lc) + ";\n"
        "Point(1) = {0, 0, 0, lc};\n"
        "Point(2) = {1, 0, 0, lc};\n"
        "Point(3) = {1, 1, 0, lc};\n"
        "Point(4) = {0, 1, 0, lc};\n"
        "Line(1) = {1, 2};\n"
        "Line(2) = {2, 3};\n"
        "Line(3) = {3, 4};\n"
        "Line(4) = {4, 1};\n"
        "Curve Loop(1) = {1, 2, 3, 4};\n"
        "Plane Surface(1) = {1};\n";
    gmsh_mesh(msh, geo);
}

void make_gmsh_mesh(disk::simplicial_mesh<double,3>& msh, double lc)
{
    std::string geo =
        "SetFactory(\"OpenCASCADE\");\n"
        "Box(1) = {0, 0, 0, 1, 1, 1};\n"
        "Mesh.MeshSizeMin = " + std::to_string(lc) + ";\n"
        "Mesh.MeshSizeMax = " + std::to_string(lc) + ";\n";
    gmsh_mesh(msh, geo);
}

} // namespace unfitted_meshes
